/**
 * Phase 3b: トピックタグの Sonnet クロスチェック
 *
 * Gemini が付与したタグを Sonnet (Claude) に検証させ、
 * 不一致があれば Sonnet 側を優先する。
 *
 * 2モデルクロスチェックにより:
 * - 一致 → 信頼度が高い（そのまま採用）
 * - 不一致 → Sonnet の推奨タグを採用（推論力が上）
 */

import Anthropic from "@anthropic-ai/sdk";
import fs from "node:fs/promises";
import { isValidTopic, getTopicsForSubject } from "../constants/topic-master.js";

const anthropicModelId = process.env.ANTHROPIC_MODEL;
if (!anthropicModelId) {
  throw new Error("ANTHROPIC_MODEL environment variable is required (do not hardcode model names)");
}

let anthropicClient: Anthropic | null = null;

function getAnthropicClient(): Anthropic {
  if (anthropicClient) return anthropicClient;
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    throw new Error("ANTHROPIC_API_KEY environment variable is required");
  }
  anthropicClient = new Anthropic({ apiKey });
  return anthropicClient;
}

export interface VerifyResult {
  label: string;
  questionNumber: number;
  geminiTags: string[];
  sonnetTags: string[];
  finalTags: string[];
  agreement: "match" | "partial" | "mismatch";
}

/**
 * 1問のタグを Sonnet で検証する
 */
async function verifySingleQuestion(
  imagePng: Buffer,
  label: string,
  subject: string,
  geminiTags: string[],
  topicList: string[],
): Promise<{ sonnetTags: string[]; agreement: "match" | "partial" | "mismatch" }> {
  const client = getAnthropicClient();

  const imageBase64 = imagePng.toString("base64");

  const prompt = `あなたは大学入試の${subject}の問題を分析し、トピックタグを検証する専門家です。

この画像は大問「${label.replace(/」/g, "")}」の切り出しです。

Gemini が以下のトピックタグを付与しました:
${geminiTags.map((t, i) => `${i + 1}. ${t}`).join("\n")}

【検証タスク】
1. 画像の問題内容を確認してください
2. Gemini のタグが妥当か判定してください:
   - 核心テーマ（その問題固有のテーマ）に対応するタグか？
   - 補助的な計算手法（汎用的な道具）のタグが混入していないか？
   - 主要なテーマが漏れていないか？
3. あなたが最適だと考えるタグをJSON配列で返してください

判断基準:「この問題を知らない人に『何の問題？』と聞かれて答える内容」にタグが対応しているか。

【重要】以下のマスターリストに存在するパスのみ使用可（5階層固定: 科目/分野/単元/サブ単元/トピック）

【マスターリスト】
${topicList.join("\n")}

最終的なタグをJSON配列のみで返してください。説明は不要です。
例: ["${subject}/分野A/単元A/サブ単元A/トピックA"]`;

  const response = await client.messages.create({
    model: anthropicModelId,
    max_tokens: 1024,
    messages: [
      {
        role: "user",
        content: [
          {
            type: "image",
            source: {
              type: "base64",
              media_type: "image/png",
              data: imageBase64,
            },
          },
          {
            type: "text",
            text: prompt,
          },
        ],
      },
    ],
  });

  const text = response.content
    .filter((c): c is Anthropic.TextBlock => c.type === "text")
    .map((c) => c.text)
    .join("");

  const usage = response.usage;
  console.log(
    `  [sonnet] input=${usage.input_tokens} output=${usage.output_tokens}`,
  );

  // JSON抽出
  let sonnetTags: string[];
  try {
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (!jsonMatch) throw new Error("No JSON array found");
    sonnetTags = JSON.parse(jsonMatch[0]);
  } catch {
    console.warn(`  ⚠ ${label} Sonnet応答のパースに失敗: ${text.slice(0, 200)}`);
    // パース失敗時は Gemini のタグをそのまま使う
    return { sonnetTags: geminiTags, agreement: "match" };
  }

  // マスターリスト照合
  const validSonnetTags = sonnetTags.filter((t) => isValidTopic(t));
  const rejected = sonnetTags.length - validSonnetTags.length;
  if (rejected > 0) {
    const invalidTags = sonnetTags.filter((t) => !isValidTopic(t));
    console.warn(
      `  ⚠ ${label} Sonnet: ${rejected}件をマスターリスト照合で除外: ${invalidTags.join(", ")}`,
    );
  }

  // 一致度判定
  const geminiSet = new Set(geminiTags);
  const sonnetSet = new Set(validSonnetTags);
  const isMatch =
    geminiSet.size === sonnetSet.size &&
    [...geminiSet].every((t) => sonnetSet.has(t));
  const hasOverlap = [...geminiSet].some((t) => sonnetSet.has(t));

  const agreement = isMatch ? "match" : hasOverlap ? "partial" : "mismatch";

  return { sonnetTags: validSonnetTags, agreement };
}

/**
 * Phase 3b: Gemini タグを Sonnet でクロスチェックする
 *
 * @returns 検証結果。finalTags に最終的なタグが入る
 */
export async function verifyTags(
  questions: { label: string; questionNumber: number; imagePng: Buffer; geminiTags: string[] }[],
  subject: string,
): Promise<VerifyResult[]> {
  const topicList = getTopicsForSubject(subject);

  console.log(
    `  🔍 ${questions.length}問のタグを Sonnet でクロスチェック中...`,
  );

  const results: VerifyResult[] = [];

  for (const q of questions) {
    console.log(`  🔍 ${q.label} 検証中...`);
    const { sonnetTags, agreement } = await verifySingleQuestion(
      q.imagePng,
      q.label,
      subject,
      q.geminiTags,
      topicList,
    );

    // 不一致時は Sonnet 側を優先
    const finalTags = agreement === "match" ? q.geminiTags : sonnetTags;

    const icon = agreement === "match" ? "✅" : agreement === "partial" ? "⚠️" : "❌";
    console.log(`  ${icon} ${q.label}: ${agreement}`);
    if (agreement !== "match") {
      console.log(`    Gemini:  ${JSON.stringify(q.geminiTags)}`);
      console.log(`    Sonnet:  ${JSON.stringify(sonnetTags)}`);
      console.log(`    → Final: ${JSON.stringify(finalTags)}`);
    }

    results.push({
      label: q.label,
      questionNumber: q.questionNumber,
      geminiTags: q.geminiTags,
